"""Build and read the canonical program wrapper."""

from __future__ import annotations

__all__ = ["P", "MARK", "pack", "extract_body", "TemplateError"]


P = 2 ** 127 - 1


# repr() escapes the template marker in the generated program.
MARK = "\x00"


_MARK_LITERAL = '"\\x00"'

_HEAD = (
    "# Zero Report - canonical wrapper (generated by pack.py).\n"
    "# Edit only the body of generate().\n"
    "import hashlib\n"
    "\n"
    "P = 2 ** 127 - 1\n"
    "\n"
    "\n"
    "def H(source):\n"
    '    return int.from_bytes(hashlib.sha256(source.encode("utf-8")).digest(), "big") % P\n'
    "\n"
    "\n"
)

_SELF = (
    "_x = " + MARK + "\n"
    "SOURCE = _x.replace(" + _MARK_LITERAL + ", repr(_x))\n"
    "\n"
)

_GEN_HEAD = "def generate():\n"

_GEN_TAIL = '\nif __name__ == "__main__":\n    print(generate())\n'


class TemplateError(ValueError):
    pass


def _normalize_body(body: str) -> str:
    if MARK in body:
        raise TemplateError("body contains the reserved marker character")
    return body.rstrip("\n")


def _indent(body: str) -> str:
    out = []
    for line in body.split("\n"):
        out.append(("    " + line + "\n") if line else "\n")
    return "".join(out)


def _template(body: str) -> str:
    return _HEAD + _SELF + _GEN_HEAD + _indent(body) + _GEN_TAIL


def pack(body: str) -> str:
    if not isinstance(body, str):
        raise TemplateError("body must be str")
    body = _normalize_body(body)
    if body == "":
        raise TemplateError("body is empty")
    v = _template(body)

    source = v.replace(MARK, repr(v))
    if MARK in source:
        raise TemplateError("internal error: marker survived packing")
    return source


_GEN_HEAD_LINE = "def generate():"
_MAIN_LINE = 'if __name__ == "__main__":'
_INDENT = "    "


def extract_body(source: str) -> str:
    if not isinstance(source, str):
        raise TemplateError("source must be str")
    lines = source.split("\n")
    try:
        start = lines.index(_GEN_HEAD_LINE)
    except ValueError as exc:
        raise TemplateError("no def generate(): line") from exc
    end = len(lines)
    for k in range(start + 1, len(lines)):
        if lines[k] == _MAIN_LINE:
            end = k
            break
    block = lines[start + 1:end]

    while block and block[-1] == "":
        block.pop()
    if not block:
        raise TemplateError("empty generate() body")
    out = []
    for i, line in enumerate(block):
        if line == "":
            out.append("")
        elif line.startswith(_INDENT):
            out.append(line[len(_INDENT):])
        else:
            raise TemplateError("body line is not indented")
    return "\n".join(out)


def extract_body_from_bytes(source: bytes) -> str:
    return extract_body(source.decode("utf-8"))


def _main(argv: list[str]) -> int:
    import sys

    if len(argv) != 3:
        sys.stderr.write("usage: pack.py body.txt out.py\n")
        return 2
    with open(argv[1], "r", encoding="utf-8") as fh:
        body = fh.read()
    src = pack(body)
    with open(argv[2], "w", encoding="utf-8", newline="") as fh:
        fh.write(src)
    return 0


if __name__ == "__main__":
    import sys

    raise SystemExit(_main(sys.argv))
